initScript:
window.rSelectedChip = 10; window.rBets = {}; window.rSpinning = false; window.rAngle = 0;
window.rOrder = [0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26];
window.rReds = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];

window.drawWheel = function() {
  const canvas = document.getElementById('roulette-canvas'); if (!canvas) return;
  const ctx = canvas.getContext('2d'); const cx = canvas.width / 2; const cy = canvas.height / 2; const radius = cx - 10;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const slice = (Math.PI * 2) / window.rOrder.length;
  window.rOrder.forEach(function(num, idx) {
    const start = window.rAngle + idx * slice; const end = start + slice;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.arc(cx, cy, radius, start, end);
    ctx.fillStyle = num === 0 ? '#15803d' : (window.rReds.includes(num) ? '#b91c1c' : '#0f172a');
    ctx.fill(); ctx.lineWidth = 1; ctx.strokeStyle = '#d97706'; ctx.stroke();
    ctx.save(); ctx.translate(cx, cy); ctx.rotate(start + slice / 2);
    ctx.textAlign = 'right'; ctx.fillStyle = '#ffffff'; ctx.font = 'bold 10px sans-serif';
    ctx.fillText(num, radius - 10, 3); ctx.restore();
  });
  ctx.beginPath(); ctx.arc(cx, cy, radius * 0.4, 0, Math.PI * 2);
  ctx.fillStyle = '#022c22'; ctx.fill(); ctx.lineWidth = 3; ctx.strokeStyle = '#f59e0b'; ctx.stroke();
  ctx.beginPath(); ctx.moveTo(cx - 9, 1); ctx.lineTo(cx + 9, 1); ctx.lineTo(cx, 22); ctx.closePath();
  ctx.fillStyle = '#fbbf24'; ctx.fill(); ctx.lineWidth = 1; ctx.strokeStyle = '#78350f'; ctx.stroke();
};

const gridEl = document.getElementById('roulette-grid');
if (gridEl) {
  let h = '';
  for (let i = 1; i <= 36; i++) {
    const bg = window.rReds.includes(i) ? 'bg-red-700 hover:bg-red-600' : 'bg-slate-900 hover:bg-slate-800';
    h += '<div onclick="window.placeBet(\'number\', ' + i + ')" class="col-span-2 sm:col-span-1 ' + bg + ' text-white py-2.5 rounded-lg cursor-pointer transition border border-slate-700 relative flex items-center justify-center font-bold">' + i +
         '<span id="chip-count-' + i + '" class="hidden absolute -top-2 -right-2 bg-amber-400 text-slate-950 rounded-full w-5 h-5 flex items-center justify-center text-[10px] font-black shadow"></span></div>';
  }
  gridEl.innerHTML = h;
}

window.setChip = function(val) {
  window.rSelectedChip = val;
  document.querySelectorAll('.chip-btn').forEach(function(btn) {
    btn.classList.remove('scale-110', 'ring-2', 'ring-amber-300', 'opacity-100'); btn.classList.add('opacity-70');
  });
  const b = document.getElementById('chip-' + val);
  if (b) { b.classList.add('scale-110', 'ring-2', 'ring-amber-300', 'opacity-100'); b.classList.remove('opacity-70'); }
};

window.updateTotalBetDisplay = function() {
  const total = Object.values(window.rBets).reduce(function(a, b) { return a + b; }, 0);
  const el = document.getElementById('roulette-total-bet'); if (el) el.innerText = total.toLocaleString() + ' pts';
};

window.placeBet = function(type, key) {
  if (window.rSpinning) return;
  const status = document.getElementById('roulette-status');
  if (state.points < window.rSelectedChip) { status.innerText = 'Insufficient bankroll!'; return; }
  const betKey = type + '_' + key;
  state.points -= window.rSelectedChip;
  window.rBets[betKey] = (window.rBets[betKey] || 0) + window.rSelectedChip;
  updatePointsDisplay(); window.updateTotalBetDisplay();
  const badgeId = 'chip-count-' + (type === 'dozen' ? 'dozen' + key : key);
  const badge = document.getElementById(badgeId);
  if (badge) { badge.classList.remove('hidden'); badge.innerText = window.rBets[betKey]; }
  status.innerText = 'Placed ' + window.rSelectedChip + ' pts on ' + (type === 'dozen' ? 'DOZEN ' + key : String(key).toUpperCase());
};

window.rClearBadges = function() {
  document.querySelectorAll('[id^="chip-count-"]').forEach(function(el) { el.classList.add('hidden'); el.innerText = ''; });
};

window.drawWheel(); window.updateTotalBetDisplay();

actionHandlers.spin:
if (window.rSpinning) return;
const status = document.getElementById('roulette-status');
const order = window.rOrder, reds = window.rReds;
const totalBet = Object.values(window.rBets).reduce(function(a, b) { return a + b; }, 0);
if (totalBet === 0) { status.innerText = 'Place at least one bet first!'; return; }
window.rSpinning = true; status.innerText = 'Spinning wheel...';
const TAU = Math.PI * 2;
const winningIndex = Math.floor(Math.random() * order.length);
const winningNumber = order[winningIndex];
const slice = TAU / order.length;
const target = -Math.PI / 2 - (winningIndex * slice + slice / 2);
const base = window.rAngle;
const delta = Math.floor(6 + Math.random() * 3) * TAU + ((((target - base) % TAU) + TAU) % TAU);
let t0 = null;
function animateSpin(ts) {
  if (!t0) t0 = ts;
  const p = (ts - t0) / 3000;
  if (p < 1) {
    window.rAngle = base + (1 - Math.pow(1 - p, 3)) * delta;
    window.drawWheel(); requestAnimationFrame(animateSpin); return;
  }
  window.rAngle = base + delta; window.drawWheel();
  let winnings = 0;
  const isRed = reds.includes(winningNumber);
  Object.keys(window.rBets).forEach(function(key) {
    const amount = window.rBets[key]; const parts = key.split('_'); const type = parts[0]; const val = parts[1];
    if (type === 'number' && parseInt(val, 10) === winningNumber) winnings += amount * 36;
    else if (type === 'color' && winningNumber !== 0 && ((val === 'red' && isRed) || (val === 'black' && !isRed))) winnings += amount * 2;
    else if (type === 'parity' && winningNumber !== 0 && ((val === 'even' && winningNumber % 2 === 0) || (val === 'odd' && winningNumber % 2 === 1))) winnings += amount * 2;
    else if (type === 'dozen' && winningNumber !== 0 && Math.ceil(winningNumber / 12) === parseInt(val, 10)) winnings += amount * 3;
  });
  state.points += winnings;
  window.rBets = {}; window.rClearBadges(); window.updateTotalBetDisplay(); updatePointsDisplay();
  window.rSpinning = false;
  const colorName = winningNumber === 0 ? 'GREEN' : (isRed ? 'RED' : 'BLACK');
  status.innerText = 'Landed on ' + winningNumber + ' (' + colorName + ')! ' + (winnings > 0 ? 'Won ' + winnings + ' pts!' : 'No win.');
}
requestAnimationFrame(animateSpin);

actionHandlers.clear:
if (window.rSpinning) return;
const totalBet = Object.values(window.rBets).reduce(function(a, b) { return a + b; }, 0);
state.points += totalBet; window.rBets = {};
window.rClearBadges(); updatePointsDisplay(); window.updateTotalBetDisplay();
document.getElementById('roulette-status').innerText = 'Bets refunded.';
